SELECT * FROM (SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, country, COUNT(*) AS num_suppliers, SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END) AS singapore_count FROM suppliers WHERE rating < 2.7 GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END, country) AS s WHERE num_suppliers < 6 ORDER BY singapore_count DESC;
